import heapq


def kLargestSubarraySums(nums, k):
    n = len(nums)
    pre = [0]
    for x in nums:
        pre.append(pre[-1] + x)
    heap = [(-pre[n], 0, n - 1)]
    seen = {n - 1}
    out = []
    while len(out) < k:
        s, l, r = heapq.heappop(heap)
        out.append(-s)
        if l < r:
            for l2, r2 in ((l + 1, r), (l, r - 1)):
                code = l2 * n + r2
                if code not in seen:
                    seen.add(code)
                    heapq.heappush(heap, (-(pre[r2 + 1] - pre[l2]), l2, r2))
    return out
